      this.$emit('update:modelValue', `fa-solid ${icon}`)
      this.close()
    },
    clear() {
      this.$emit('update:modelValue', '')
      this.close()
    },
    // Persist a manually typed class (e.g. "fa-brands fa-trello")
    applyCustom() {
      const value = this.custom.trim()
      if (!value) return
      this.$emit('update:modelValue', this.iconClass(value))
      this.close()
    }
