          <i :class="['fa-solid text-xs', isVirtualBoard ? 'fa-inbox text-warning' : 'fa-calendar-days text-primary']"></i>
          <span class="font-medium text-sm truncate max-w-[16rem]">{{ activeBoardTitle }}</span>
